@Component
class RawArgsRunner implements CommandLineRunner {
    public void run(String... args) {
        for (String arg : args) {
            System.out.println("Argument: " + arg);
        }
    }
}
// Uruchomienie: java -jar app.jar --mode=import plik.csv --verbose
// args = ["--mode=import", "plik.csv", "--verbose"] - BEZ zadnego parsowania

@Component
class ParsedArgsRunner implements ApplicationRunner {
    public void run(ApplicationArguments args) {
        args.getOptionNames();               // ["mode", "verbose"]
        args.getOptionValues("mode");         // ["import"]
        args.getNonOptionArgs();              // ["plik.csv"]
    }
}
// Ten sam "--mode=import plik.csv --verbose" - ale JUZ SPARSOWANY na opcje i pozycyjne
